def connected_components(n, graph):
    visited = [False] * n
    sizes = []
    for s in range(n):
        if visited[s]:
            continue
        visited[s] = True
        stack = [s]
        size = 0
        while stack:
            cur = stack.pop()
            size += 1
            for nxt in graph[cur]:
                if not visited[nxt]:
                    visited[nxt] = True
                    stack.append(nxt)
        sizes.append(size)
    return len(sizes), sizes

