from collections import deque


def shortest_with_break(grid, limit):
    n, m = len(grid), len(grid[0])
    dist = [[[0] * (limit + 1) for _ in range(m)] for _ in range(n)]
    dr, dc = [-1, 1, 0, 0], [0, 0, -1, 1]
    q = deque([(0, 0, 0)])
    dist[0][0][0] = 1
    while q:
        r, c, k = q.popleft()
        if (r, c) == (n - 1, m - 1):
            return dist[r][c][k]
        for i in range(4):
            nr, nc = r + dr[i], c + dc[i]
            if not (0 <= nr < n and 0 <= nc < m):
                continue
            if grid[nr][nc] == 0 and dist[nr][nc][k] == 0:
                dist[nr][nc][k] = dist[r][c][k] + 1
                q.append((nr, nc, k))
            elif grid[nr][nc] == 1 and k < limit and dist[nr][nc][k + 1] == 0:
                dist[nr][nc][k + 1] = dist[r][c][k] + 1
                q.append((nr, nc, k + 1))
    return -1

def lcs_with_path(a, b):
    n, m = len(a), len(b)
    dp = [[0] * (m + 1) for _ in range(n + 1)]
    for i in range(1, n + 1):
        for j in range(1, m + 1):
            if a[i - 1] == b[j - 1]:
                dp[i][j] = dp[i - 1][j - 1] + 1
            else:
                dp[i][j] = max(dp[i - 1][j], dp[i][j - 1])
    path = []
    i, j = n, m
    while i > 0 and j > 0:
        if a[i - 1] == b[j - 1]:
            path.append(a[i - 1])
            i -= 1
            j -= 1
        elif dp[i - 1][j] >= dp[i][j - 1]:
            i -= 1
        else:
            j -= 1
    return dp[n][m], "".join(reversed(path))
